pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set concrete values: betLimit = 1 ether, difficulty = 10
        // Owner calls OpenToThePublic() and sets betLimit & difficulty
        c.OpenToThePublic();
        c.AdjustBetAmounts(1 ether);
        c.AdjustDifficulty(10);

        // Player1 (an EOA) wagers exactly betLimit
        address player1 = address(0x1234);
        vm.deal(player1, 1 ether);
        vm.prank(player1);
        c.wager{value: 1 ether}();

        // Player1 calls play() with some block advancement to make it valid
        vm.roll(block.number + 1);
        vm.prank(player1);
        c.play();

        // Now a non-owner tries to call OpenToThePublic() again – should revert in reference
        address attacker = address(0x5678);
        vm.prank(attacker);
        // The call will either revert (reference) or succeed (buggy) – capture the boolean
        bool ok;
        try c.OpenToThePublic() { ok = true; } catch { ok = false; }
        // In reference version, attacker cannot call OpenToThePublic -> ok = false
        // In buggy version, modifier is empty -> call succeeds -> ok = true
        // We assert that the reference version makes the call fail (ok == false)
        // This assertion passes for reference (ok = false) and fails for buggy (ok = true)
        assertTrue(!ok);
    }
}

