        // Verify that the reference rejects (ok == false) and buggy allows (ok == true)
        // We expect reference to revert => ok == false, but we want test to pass on reference, so we assert ok == false
        // BUT NOTE: For the test to FAIL on buggy version, we need to assert something that is true on reference but false on buggy.
        // On reference, play reverts because player hasn't wagered, so ok is false.
        // On buggy, play does not revert (modifier removed), so it runs the logic and depending on randomSeed may change balance.
        // Let's make the scenario deterministic: randomSeed is private and not set, defaults to 0.
        // block.number starts at 0, blockhash(0) = 0x...0, so winningNumber = uint256(keccak256(abi.encodePacked(0, player, 0))) % 2 + 1 -> either 1 or 2.
        // We'll just assert that after the call, the contract balance is unchanged on reference (since play reverts, no ether moved)
        // On buggy, play might send ether to whale or winner, changing balance.

        uint256 balanceBefore = address(c).balance;
        vm.prank(player);
        bool ok2;
        try c.play() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        uint256 balanceAfter = address(c).balance;
        // Reference: play reverts (ok2 false) and balance unchanged.
        // Buggy: play might not revert and could change balance.
        // We assert that if play was successful (ok2 true), then the balance must have changed (since ether sent to whale or winner).
